<script setup>
import { ref, onMounted } from 'vue'
import SiteHeader from '../components/common/SiteHeader.vue'
import api from '../services/api.js'
import { toast } from '../services/toast.js'
import { roomModes } from '../config/roomModes.js'
import GameContentAdmin from '../components/games/GameContentAdmin.vue'
import GameCatalogAdmin from '../components/games/GameCatalogAdmin.vue'
import SoundEffectsAdmin from '../components/meeting/SoundEffectsAdmin.vue'
const overview=ref(null),users=ref([]),loading=ref(false),usersLoading=ref(false),busy=ref(''),email=ref(''),nextCursor=ref(null),cursor=ref(''),history=ref([]),tab=ref('users')
function duration(ms){const minutes=Math.floor((ms || 0)/60000);return minutes>=60?`${Math.floor(minutes/60)}j ${minutes%60}m`:`${minutes}m`}
function date(ms){return ms?new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short'}).format(new Date(ms)):'—'}
async function loadUsers(reset=false){
  if(reset){cursor.value='';history.value=[]}
  usersLoading.value=true
  try{const response=await api.get('/admin/users',{params:{email:email.value.trim() || undefined,cursor:cursor.value || undefined}});users.value=response.data.data.users;nextCursor.value=response.data.data.nextCursor}
  catch(error){toast.error(error)}finally{usersLoading.value=false}
}
async function loadOverview(){try{overview.value=(await api.get('/admin/overview')).data.data}catch(error){toast.error(error)}}
async function refresh(){if(loading.value)return;loading.value=true;try{await Promise.all([loadOverview(),loadUsers()])}finally{loading.value=false}}
async function page(next){if(next){history.value.push(cursor.value);cursor.value=nextCursor.value}else cursor.value=history.value.pop() || '';await loadUsers()}
async function changeAccess(user){
  if(busy.value)return
  busy.value=user.uid
  const access=user.access==='full'?'pending':'full'
  try{await api.patch(`/admin/users/${encodeURIComponent(user.uid)}/access`,{access});user.access=access;toast.success(access==='full'?'Akses penuh telah diberikan.':'Akses host dicabut untuk sesi baru.');await loadOverview()}
  catch(error){toast.error(error)}finally{busy.value=''}
}
onMounted(refresh)
</script>
<template><SiteHeader /><main class="admin-page"><div class="admin-heading"><div><span class="admin-kicker">RUANG KONTROL · ADMIN</span><h1>Di balik ruang yang ramai.</h1><p>Kelola akses anggota dan lihat aktivitas MeetSpace.</p></div><button class="ms-button ms-button-outline" :disabled="loading" @click="refresh">{{loading?'Memuat…':'Refresh ↻'}}</button></div>
  <div v-if="!overview && loading" class="ms-card admin-loading" role="status">Menyiapkan ringkasan klub…</div>
  <div v-else-if="!overview" class="ms-card admin-loading"><h2>Ringkasan belum tersedia.</h2><p>Coba Refresh untuk memuat data dari server.</p></div>
  <template v-if="overview"><section class="stat-grid" aria-label="Ringkasan penggunaan"><article class="ms-card"><span>AKUN TERCATAT</span><strong>{{overview.users}}</strong><small>{{overview.pending}} menunggu akses host</small></article><article class="ms-card"><span>AKSES PENUH</span><strong>{{overview.full}}</strong><small>Akun yang boleh membuat room</small></article><article class="ms-card"><span>DURASI PESERTA</span><strong>{{duration(overview.durationMs)}}</strong><small>Akumulasi sesi yang sudah selesai</small></article><article class="ms-card"><span>ROOM DIBUAT</span><strong>{{overview.rooms}}</strong><small>{{overview.activeRooms}} room aktif menurut event terakhir</small></article></section>
    <div class="usage-strip"><span><i :class="{live:overview.lastEventAt}"></i>{{overview.lastEventAt?`${overview.activeParticipants} peserta aktif · ${overview.sessions} sesi tercatat`:'Belum ada data sesi meeting'}}</span><small>{{overview.lastEventAt?`Event terakhir: ${date(overview.lastEventAt)}`:'Durasi akan muncul setelah event LiveKit diterima.'}}</small></div>
  </template>
  <div class="admin-tabs" role="tablist" aria-label="Data admin"><button v-for="[id,label] in [['users','♧ Anggota & akses'],['usage','◷ Penggunaan'],['catalog','✦ Katalog game'],['games','✎ Bank soal'],['sounds','♫ Sound FX'],['audit','↺ Riwayat akses']]" :key="id" role="tab" :aria-selected="tab===id" :class="{active:tab===id}" @click="tab=id">{{label}}</button></div>
  <section v-if="tab==='users'" class="ms-card admin-panel"><div class="panel-top"><div><h2>Semua anggota, satu tempat.</h2><p>Akun yang sudah memverifikasi email dapat bergabung sebagai peserta. Berikan akses penuh untuk membuat room.</p></div><form @submit.prevent="loadUsers(true)"><label class="sr-only" for="user-search">Cari email lengkap</label><input id="user-search" v-model="email" class="ms-input" type="search" placeholder="Cari email lengkap…" /><button class="ms-button ms-button-primary" :disabled="usersLoading">Cari</button></form></div>
    <div class="table-scroll"><table><thead><tr><th>Anggota</th><th>Bergabung</th><th>Terakhir aktif</th><th>Akses</th><th>Kelola</th></tr></thead><tbody><tr v-for="user in users" :key="user.uid"><td><strong>{{user.displayName || user.email || 'Anggota'}}</strong><small v-if="user.displayName">{{user.email}}</small><small class="uid">{{user.uid}}</small></td><td>{{date(user.createdAt)}}</td><td>{{date(user.lastSeenAt)}}</td><td><span class="access-badge" :class="{full:user.access==='full'}">{{user.role==='admin'?'Admin':user.access==='full'?'Akses penuh':'Peserta'}}</span></td><td><button v-if="user.role!=='admin'" class="ms-button" :class="user.access==='full'?'ms-button-outline':'ms-button-accent'" :disabled="Boolean(busy)" @click="changeAccess(user)">{{busy===user.uid?'Menyimpan…':user.access==='full'?'Cabut akses host':'Beri akses penuh'}}</button><span v-else class="ms-muted">Dikelola server</span></td></tr><tr v-if="!users.length"><td colspan="5" class="empty-state">{{usersLoading?'Memuat anggota…':'Belum ada akun yang cocok. Akun tercatat setelah masuk ke aplikasi.'}}</td></tr></tbody></table></div>
    <footer class="table-footer"><span>Menampilkan hingga 50 akun · pencarian email harus lengkap</span><div><button :disabled="!history.length || usersLoading" @click="page(false)">← Sebelumnya</button><button :disabled="!nextCursor || usersLoading" @click="page(true)">Berikutnya →</button></div></footer>
  </section>
  <section v-else-if="tab==='usage' && overview" class="usage-grid"><div class="ms-card admin-panel"><h2>Ruang yang dipilih.</h2><p class="ms-muted">Jumlah room dibuat per mode.</p><div v-for="mode in overview.modes" :key="mode.mode" class="mode-bar"><div><span>{{roomModes[mode.mode]?.name || mode.mode}}</span><strong>{{mode.count}}</strong></div><div class="bar-track"><i :style="{width:`${overview.rooms?mode.count/overview.rooms*100:0}%`}"></i></div></div></div><div class="ms-card admin-panel"><h2>Sesi terbaru.</h2><p class="ms-muted">25 sesi terakhir. Durasi dijumlahkan per peserta, bukan durasi rekaman.</p><div class="table-scroll"><table><thead><tr><th>Peserta / room</th><th>Mulai</th><th>Durasi</th></tr></thead><tbody><tr v-for="session in overview.recent" :key="session.id"><td><strong>{{session.participantName}}</strong><small>{{session.roomName}}</small></td><td>{{date(session.startedAt)}}</td><td>{{session.endedAt===null?'Berlangsung':duration(session.durationMs)}}</td></tr><tr v-if="!overview.recent.length"><td colspan="3">Belum ada sesi tercatat.</td></tr></tbody></table></div></div></section>
  <GameContentAdmin v-else-if="tab==='games'" />
  <GameCatalogAdmin v-else-if="tab==='catalog'" />
  <SoundEffectsAdmin v-else-if="tab==='sounds'" />
  <section v-else-if="tab==='audit' && overview" class="ms-card admin-panel"><h2>Perubahan akses terakhir.</h2><div class="table-scroll"><table><thead><tr><th>Akun</th><th>Perubahan</th><th>Waktu</th><th>Admin (UID)</th></tr></thead><tbody><tr v-for="event in overview.audit" :key="event.id"><td>{{event.email || event.subjectUid}}</td><td>{{event.after==='full'?'Akses penuh diberikan':'Akses host dicabut'}}</td><td>{{date(event.createdAt)}}</td><td>{{event.actorUid}}</td></tr><tr v-if="!overview.audit.length"><td colspan="4">Belum ada perubahan akses.</td></tr></tbody></table></div></section>
  <p class="admin-footnote">Statistik hanya memuat metadata penggunaan. Isi chat, video, dan audio tidak disimpan di dashboard. Pencabutan akses host berlaku untuk pembuatan room dan koneksi host berikutnya.</p>
</main></template>
<style scoped>
.admin-page{width:min(1240px,calc(100% - 40px));margin:45px auto 70px}.admin-heading{display:flex;align-items:center;justify-content:space-between;gap:25px;margin-bottom:32px}.admin-kicker{font-size:11px;font-weight:1000;letter-spacing:2px}h1{font-size:clamp(32px,4vw,49px);margin:15px 0 10px}.admin-heading p,.panel-top p{color:var(--text-secondary);font-size:14px;margin:0}.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:19px}.stat-grid article{padding:25px;display:flex;flex-direction:column;gap:10px}.stat-grid article:nth-child(2){background:var(--color-primary);color:#182a25}.stat-grid article>span{font-size:10px;letter-spacing:1.5px;font-weight:1000}.stat-grid strong{font-family:var(--font-display);font-size:43px}.stat-grid small{font-size:11px}.usage-strip{display:flex;justify-content:space-between;align-items:center;gap:15px;margin:25px 0 35px;font-size:13px}.usage-strip small{color:var(--text-secondary)}.usage-strip i{display:inline-block;width:8px;height:8px;background:var(--text-secondary);border-radius:50%;margin-right:8px}.usage-strip i.live{background:var(--color-primary)}.admin-tabs{display:flex;gap:8px;margin-bottom:20px;overflow-x:auto;padding-bottom:5px}.admin-tabs button{white-space:nowrap;padding:12px 18px;border:2px solid var(--border-color);border-radius:12px;background:var(--bg-surface);color:var(--text-primary);font-weight:900}.admin-tabs button.active{background:var(--color-secondary);color:#292e29;box-shadow:3px 3px 0 var(--shadow-color)}.admin-panel{padding:28px;min-width:0}h2{font-size:25px;margin:0 0 10px}.panel-top{display:flex;justify-content:space-between;align-items:center;gap:25px;margin-bottom:24px}.panel-top form{display:flex;gap:9px;min-width:310px}.panel-top input{min-width:0}.table-scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}th{font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--text-secondary);padding:14px 12px;border-block:1px solid var(--border-color)}td{padding:17px 12px;border-bottom:1px dashed color-mix(in srgb,var(--border-color) 35%,transparent);vertical-align:middle}td strong,td small{display:block}td small{color:var(--text-secondary);margin-top:4px}.uid{font-size:10px;max-width:210px;overflow:hidden;text-overflow:ellipsis}td .ms-button{padding:8px 12px;font-size:11px;white-space:nowrap}.access-badge{display:inline-block;background:var(--bg-elevated);border:1px solid var(--border-color);border-radius:20px;padding:4px 9px;white-space:nowrap;font-weight:900}.access-badge.full{background:#59b292;color:#182a25}.table-footer{display:flex;justify-content:space-between;gap:20px;padding-top:20px;font-size:11px;color:var(--text-secondary)}.table-footer>div{display:flex;gap:15px}.table-footer button{background:none;border:0;color:var(--text-primary);font-weight:900}.usage-grid{display:grid;grid-template-columns:.7fr 1.3fr;gap:25px}.mode-bar{margin-top:25px}.mode-bar>div:first-child{display:flex;justify-content:space-between;font-size:13px;gap:15px;margin-bottom:8px}.bar-track{height:10px;background:var(--bg-elevated);border:1px solid var(--border-color);border-radius:10px;overflow:hidden}.bar-track i{display:block;height:100%;background:var(--color-primary)}.admin-footnote{font-size:11px;color:var(--text-secondary);max-width:900px;margin-top:24px}.admin-loading{padding:40px;margin:30px 0}.empty-state{text-align:center;padding:40px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:1000px){.stat-grid{grid-template-columns:repeat(2,1fr)}.panel-top{display:block}.panel-top form{margin-top:20px;min-width:0}.usage-grid{grid-template-columns:1fr}}@media(max-width:600px){.admin-heading{align-items:start;flex-direction:column}.stat-grid{gap:12px}.stat-grid article{padding:18px}.stat-grid strong{font-size:34px}.usage-strip,.table-footer{flex-direction:column;align-items:start}.admin-panel{padding:18px}.admin-page{width:calc(100% - 28px)}}
</style>
